import{_ as a,o as t,c as r,al as o}from"./chunks/framework.7vp1BMOE.js";const n="/px4_user_guide/assets/tag_e_with_coin.BGLq3wIf.png",i="/px4_user_guide/assets/qgc_camera_settings.BXAuQ6SB.png",_=JSON.parse('{"title":"AirPixel TAG-E (Sony ILX-LR1 Camera Control and Geotagging)","description":"","frontmatter":{},"headers":[],"relativePath":"en/camera/airpixel_tag_e.md","filePath":"en/camera/airpixel_tag_e.md"}'),c={name:"en/camera/airpixel_tag_e.md"};function l(d,e,s,h,g,m){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="airpixel-tag-e-sony-ilx-lr1-camera-control-and-geotagging" tabindex="-1">AirPixel TAG-E (Sony ILX-LR1 Camera Control and Geotagging) <a class="header-anchor" href="#airpixel-tag-e-sony-ilx-lr1-camera-control-and-geotagging" aria-label="Permalink to &quot;AirPixel TAG-E (Sony ILX-LR1 Camera Control and Geotagging)&quot;">​</a></h1><p>The <a href="https://airpixel.cz/" target="_blank" rel="noreferrer">AirPixel TAG-E</a> is a camera controller and EXIF/XMP geotagger for the Sony ILX-LR1. It connects to the camera with a single USB-C cable and to PX4 over MAVLink, and acts as a <a href="./../camera/mavlink_v2_camera">MAVLink camera</a> using <a href="https://mavlink.io/en/services/camera.html" target="_blank" rel="noreferrer">Camera Protocol v2</a>.</p><p><em>QGroundControl</em> detects the camera automatically and shows its shutter, video, exposure and configuration controls. TAG-E writes position, altitude and camera attitude into the EXIF and XMP of every photo on the camera&#39;s SD card during the flight, so no log-based geotagging is needed afterwards.</p><p><img src="'+n+'" alt="AirPixel TAG-E"></p><h2 id="key-features" tabindex="-1">Key Features <a class="header-anchor" href="#key-features" aria-label="Permalink to &quot;Key Features&quot;">​</a></h2><ul><li>Full MAVLink Camera Protocol v2 control of the Sony ILX-LR1 (ISO, aperture, shutter speed, exposure compensation, exposure mode, AF mode, photo/video).</li><li>Automatic EXIF and XMP geotagging with position, altitude and camera roll/pitch/yaw, at the camera&#39;s full trigger rate.</li><li>Clock synchronisation with the flight controller using the MAVLink <a href="https://mavlink.io/en/services/timesync.html" target="_blank" rel="noreferrer">TIMESYNC</a> protocol.</li><li>Lever-arm correction from antenna-to-camera offsets, optional rangefinder, GPS/IMU accuracy and custom label tags, PPK output, and video geotagging via subtitles.</li><li>Camera clock set automatically from GPS time.</li></ul><h2 id="wiring" tabindex="-1">Wiring <a class="header-anchor" href="#wiring" aria-label="Permalink to &quot;Wiring&quot;">​</a></h2><p>Connect TAG-E&#39;s IO-B connector to an unused serial port on the flight controller, such as <code>TELEM2</code>, and TAG-E&#39;s USB-C port to the camera. TAG-E needs a 5V supply able to deliver at least 2A.</p><p>Pinouts are in the <a href="https://airpixel.cz/docs/tag-e-pinouts/" target="_blank" rel="noreferrer">TAG-E pinout manual</a>.</p><h2 id="px4-configuration" tabindex="-1">PX4 Configuration <a class="header-anchor" href="#px4-configuration" aria-label="Permalink to &quot;PX4 Configuration&quot;">​</a></h2><p>TAG-E uses the component ID <code>MAV_COMP_ID_CAMERA</code> (100). Configure an unused MAVLink instance for the port it is connected to. The table below shows the settings for <code>TELEM2</code> using the <code>MAV_1_*</code> parameters (if using another port or instance, set the corresponding unused <code>MAV_n_*</code> parameters and the baud rate parameter for that port):</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Value</th></tr></thead><tbody><tr><td><a href="./../advanced_config/parameter_reference#MAV_1_CONFIG">MAV_1_CONFIG</a></td><td><code>TELEM 2</code></td></tr><tr><td><a href="./../advanced_config/parameter_reference#SER_TEL2_BAUD">SER_TEL2_BAUD</a></td><td><code>921600</code></td></tr><tr><td><a href="./../advanced_config/parameter_reference#MAV_1_MODE">MAV_1_MODE</a></td><td><code>Onboard</code></td></tr><tr><td><a href="./../advanced_config/parameter_reference#MAV_1_RATE">MAV_1_RATE</a></td><td><code>0</code></td></tr><tr><td><a href="./../advanced_config/parameter_reference#MAV_1_FORWARD">MAV_1_FORWARD</a></td><td><code>Enabled</code></td></tr></tbody></table><p>Reboot the flight controller. When the camera is online, the TAG-E LED turns green and the camera panel appears in <em>QGroundControl</em>.</p><p>TAG-E requests the messages it needs using <a href="https://mavlink.io/en/messages/common.html#MAV_CMD_SET_MESSAGE_INTERVAL" target="_blank" rel="noreferrer">MAV_CMD_SET_MESSAGE_INTERVAL</a>: <code>SYSTEM_TIME</code> at 1Hz, <code>ATTITUDE</code> at 10Hz, and <code>GPS_RAW_INT</code> and <code>GLOBAL_POSITION_INT</code> at a rate that depends on its configuration. It also uses the <code>TIMESYNC</code> protocol to synchronise its clock with the flight controller.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>TAG-E units with firmware older than <code>0_193</code> use 230400 baud. See the manufacturer&#39;s <a href="https://airpixel.cz/docs/tag-e-mavlink-connection-px4/" target="_blank" rel="noreferrer">PX4 connection manual</a> for changing the baud rate, and the <a href="https://airpixel.cz/docs/gps-delay-calculation/" target="_blank" rel="noreferrer">GPS delay calculation</a> for the best geotag accuracy.</p></div><h2 id="camera-control-in-qgroundcontrol" tabindex="-1">Camera Control in QGroundControl <a class="header-anchor" href="#camera-control-in-qgroundcontrol" aria-label="Permalink to &quot;Camera Control in QGroundControl&quot;">​</a></h2><p>When the camera is online, <em>QGroundControl</em> shows the camera panel on the right of the Fly view: the shutter button, a photo/video switch, and the photo count or recording time. The gear icon under the shutter button opens the camera settings: exposure mode, aperture, shutter speed, ISO, focus mode and image resolution, plus TAG-E functions such as remote SD card format, a custom EXIF label, landing detection and photo mode.</p><p><img src="'+i+'" alt="QGroundControl camera settings for the Sony ILX-LR1 with TAG-E"></p><h2 id="triggering" tabindex="-1">Triggering <a class="header-anchor" href="#triggering" aria-label="Permalink to &quot;Triggering&quot;">​</a></h2><p>PX4 re-emits the image and video capture commands in missions (<code>MAV_CMD_IMAGE_START_CAPTURE</code>, <code>MAV_CMD_IMAGE_STOP_CAPTURE</code>, <code>MAV_CMD_VIDEO_START_CAPTURE</code>, <code>MAV_CMD_VIDEO_STOP_CAPTURE</code>) to <code>MAV_COMP_ID_CAMERA</code>, so they reach TAG-E directly. The camera can also be triggered from the <em>QGroundControl</em> camera panel.</p><h2 id="further-information" tabindex="-1">Further Information <a class="header-anchor" href="#further-information" aria-label="Permalink to &quot;Further Information&quot;">​</a></h2><ul><li><a href="https://airpixel.cz/" target="_blank" rel="noreferrer">TAG-E product page</a></li><li><a href="https://airpixel.cz/nw/guides/px4-ilx-lr1-camera-control/" target="_blank" rel="noreferrer">PX4 camera control guide for the ILX-LR1</a> (AirPixel)</li><li><a href="https://airpixel.cz/docs-tag-e/" target="_blank" rel="noreferrer">TAG-E documentation</a></li><li><a href="./../camera/mavlink_v2_camera">MAVLink Cameras (Camera Protocol v2)</a></li></ul>',22)])])}const p=a(c,[["render",l]]);export{_ as __pageData,p as default};
